css:
/* =========================================================
   FORM · 设计宪法（简版）
   Dials: VARIANCE 6 / MOTION 4 / DENSITY 5
   色能分配 60-30-10 —— 骨白 60% ／ 结构灰蓝 30% ／ 钴蓝·洋红 10%
   单一光源：全页阴影向量统一为 135° 柔光
   模度：全部尺寸走 4px 阶梯（字距例外见下）
   ========================================================= */

:root{
  --bone:      #F7F5F0;
  --bone-dip:  #EFEBE3;
  --ink:       #0B0F1A;
  --ink-2:     #2A3550;
  --muted:     #565E72;
  --line:      rgba(11,15,26,.16);
  --line-hard: rgba(11,15,26,.42);

  --cobalt:    #1B3AC4;
  --cobalt-dp: #16309E;
  --magenta:   #B00070;
  --cobalt-tint: rgba(27,58,196,.07);
  --magenta-tint: rgba(176,0,112,.07);

  --paper:     #FBFAF7;
  --mist:      #DDE3E6;

  --sp-1:4px; --sp-2:8px; --sp-3:12px; --sp-4:16px; --sp-5:20px;
  --sp-6:24px; --sp-8:32px; --sp-10:40px; --sp-12:48px; --sp-16:64px;

  --ease: cubic-bezier(.16,1,.3,1);
  --light: 0 16px 32px -12px rgba(11,15,26,.10);

  --f-sans:'Helvetica Neue',Helvetica,Arial,'PingFang SC','Hiragino Sans GB','Microsoft YaHei','Noto Sans SC',sans-serif;
  --f-mono:ui-monospace,'SFMono-Regular',Menlo,Consolas,'Noto Sans Mono',monospace;
}

*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{
  margin:0;background:var(--bone);color:var(--ink);
  font-family:var(--f-sans);font-size:16px;line-height:1.6;
  -webkit-font-smoothing:antialiased;font-variant-numeric:tabular-nums;
}
h1,h2,h3,h4,p,ul,dl,figure{margin:0}
ul{padding:0;list-style:none}
a{color:inherit}
button{font:inherit;color:inherit}
::selection{background:var(--cobalt);color:var(--bone)}

:focus-visible{outline:3px solid var(--cobalt);outline-offset:3px;border-radius:2px}
.site-foot :focus-visible,.plate :focus-visible{outline-color:#fff}

.sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;
  clip-path:inset(50%);white-space:nowrap;border:0}
.skip{position:absolute;left:var(--sp-4);top:-80px;z-index:20;background:var(--ink);color:var(--bone);
  padding:var(--sp-3) var(--sp-5);font-size:14px;text-decoration:none;transition:top .2s var(--ease)}
.skip:focus{top:var(--sp-4)}

/* ============ 头部 ============ */
.site-head{
  display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:var(--sp-8);
  padding:var(--sp-5) clamp(20px,4vw,56px);
  border-bottom:1px solid var(--line-hard);
  position:sticky;top:0;z-index:10;
  background:rgba(247,245,240,.94);backdrop-filter:blur(12px);
}
.wordmark{font-size:28px;font-weight:700;letter-spacing:-.045em;text-decoration:none}
.reg{font-size:.5em;vertical-align:super;font-weight:400}
.site-nav{display:flex;gap:var(--sp-6);justify-self:center}
.site-nav a{font-size:14px;text-decoration:none;padding:var(--sp-2) 0;border-bottom:1px solid transparent;
  transition:border-color .18s var(--ease)}
.site-nav a:hover{border-bottom-color:var(--ink)}
.head-cta{
  font-size:14px;font-weight:600;text-decoration:none;white-space:nowrap;
  background:var(--cobalt);color:var(--bone);
  padding:var(--sp-3) var(--sp-5);min-height:44px;display:inline-flex;align-items:center;
  transition:background .18s var(--ease),transform .18s var(--ease)}
.head-cta:hover{background:var(--cobalt-dp);transform:translateY(-1px)}
.head-cta:active{transform:translateY(0) scale(.985)}

/* ============ 首屏 ============ */
.hero{padding:clamp(32px,5vw,72px) clamp(20px,4vw,56px) clamp(40px,5vw,64px);
  border-bottom:1px solid var(--line-hard)}
.eyebrow{font-family:var(--f-mono);font-size:12px;font-weight:700;
  letter-spacing:.06em;color:var(--magenta);margin-bottom:var(--sp-10)}
.hero-grid{display:grid;grid-template-columns:7fr 5fr;gap:var(--sp-10);align-items:end}
.hero h1{
  font-size:clamp(64px,12.2vw,176px);line-height:.84;font-weight:600;
  letter-spacing:-.05em;margin:0;
}
.hero-side{padding-bottom:var(--sp-3)}
.hero-lead{font-size:18px;line-height:1.55;max-width:34ch;color:var(--ink-2);
  border-top:1px solid var(--line-hard);padding-top:var(--sp-5)}
.hero-facts{margin-top:var(--sp-8);display:grid;gap:var(--sp-3)}
.hero-facts>div{display:grid;grid-template-columns:9ch 1fr;gap:var(--sp-4);
  border-top:1px solid var(--line);padding-top:var(--sp-3)}
.hero-facts dt{font-size:13px;color:var(--muted)}
.hero-facts dd{font-size:14px;font-weight:600}

/* ============ 区块栏 ============ */
.section-bar{
  display:flex;justify-content:space-between;align-items:center;gap:var(--sp-6);
  padding:var(--sp-4) clamp(20px,4vw,56px);
  border-bottom:1px solid var(--line-hard);
}
.section-bar h2{font-size:13px;font-weight:600;letter-spacing:.1em;font-family:var(--f-mono)}
.section-bar--plain{background:var(--bone-dip)}
.svc-hint{font-size:14px;color:var(--muted)}

/* ============ 筛选 tablist ============ */
.tabs{display:flex;gap:var(--sp-1);flex-wrap:wrap}
.tabs button{
  border:1px solid transparent;background:none;cursor:pointer;
  padding:var(--sp-2) var(--sp-4);min-height:44px;min-width:44px;
  font-size:14px;font-weight:600;
  transition:background .18s var(--ease),color .18s var(--ease),border-color .18s var(--ease);
}
.tabs button:hover{background:var(--cobalt-tint)}
.tabs button[aria-selected="true"]{background:var(--cobalt);color:var(--bone);border-color:var(--cobalt)}
.tabs button[aria-selected="true"]::before{content:"";display:inline-block;
  width:6px;height:6px;background:#FF4FB0;margin-right:var(--sp-2);vertical-align:middle}
.tabs button:active{transform:scale(.97)}

/* ============ 项目网格：7:5 非对称 ============ */
/* 桌面端两行等高。左卡跨两行，其面板 flex:1 后必然等于右列两张叠卡总高，底边对齐。 */
.grid{
  display:grid;grid-template-columns:7fr 5fr;
  padding:var(--sp-10) clamp(20px,4vw,56px) var(--sp-16);
  gap:var(--sp-10) var(--sp-8);
}
.card{display:flex;flex-direction:column;transition:transform .32s var(--ease)}
.card--wide{grid-row:span 2}
.card:focus-visible{outline-offset:6px}

.plate{
  position:relative;overflow:hidden;flex:1 1 auto;min-height:220px;
  border:1px solid var(--line-hard);
  transition:box-shadow .32s var(--ease);
  box-shadow:0 0 0 rgba(11,15,26,0);
}
.card:hover .plate,.card:focus-visible .plate{box-shadow:var(--light)}
.card:hover{transform:translateY(-4px)}

.idx{position:absolute;top:var(--sp-5);left:var(--sp-5);
  font-family:var(--f-mono);font-size:12px;font-weight:700;letter-spacing:.14em;z-index:2}
.idx--light{color:var(--bone)}

.art-word{font-size:clamp(30px,3.4vw,58px);line-height:.96;font-weight:600;
  letter-spacing:-.04em;position:absolute;left:var(--sp-5);bottom:var(--sp-8);z-index:2}
.card--wide .art-word{font-size:clamp(38px,4.4vw,76px)}
.art-word--dark{color:var(--ink)}
.art-word--light{color:var(--bone)}
.art-note{position:absolute;left:var(--sp-5);bottom:var(--sp-5);
  font-family:var(--f-mono);font-size:12px;letter-spacing:.08em;z-index:2}
.art-note--light{color:rgba(247,245,240,.82)}

/* 四张项目面：同一钴蓝色系内的明度阶梯，不再是四色混战 */
.plate--cobalt{background:var(--cobalt);color:var(--bone)}
.plate--cobalt .art-note{color:rgba(247,245,240,.8)}
.ring{position:absolute;right:-56px;bottom:-72px;width:min(56%,220px);aspect-ratio:1;
  border:36px solid var(--mist);border-radius:50%;opacity:.92}
.plate--paper{background:var(--paper)}
.sheet{position:absolute;inset:12% 11% 10%;background:var(--bone-dip);
  border:1px solid var(--line-hard);padding:var(--sp-6);
  transform:rotate(-4deg);transform-origin:left bottom;
  box-shadow:8px 10px 0 rgba(11,15,26,.07)}
.sheet-lead{font-size:clamp(22px,2.2vw,32px);line-height:1.06;font-weight:600;letter-spacing:-.03em}
.sheet-rule{display:block;height:1px;background:var(--line-hard);margin:var(--sp-5) 0 var(--sp-4)}
.sheet-note{font-family:var(--f-mono);font-size:12px;letter-spacing:.06em;color:var(--muted)}
.plate--mist{background:var(--mist)}
.plate--mist .art-word{top:50%;bottom:auto;transform:translateY(-50%);
  font-size:clamp(30px,3.2vw,54px);color:var(--ink)}
.arc{position:absolute;right:9%;bottom:0;width:min(48%,170px);aspect-ratio:1/1;
  border:1px solid var(--ink);border-bottom:0;border-radius:200px 200px 0 0}
.plate--ink{background:var(--ink);color:var(--bone)}

.cap{display:flex;justify-content:space-between;align-items:baseline;gap:var(--sp-4);
  margin-top:var(--sp-4);border-top:1px solid var(--line-hard);padding-top:var(--sp-3)}
.cap h3{font-size:17px;font-weight:600;letter-spacing:-.01em}
.cap-meta{font-size:13px;color:var(--muted);text-align:right}
.cap-line{font-size:14px;line-height:1.6;color:var(--ink-2);margin-top:var(--sp-2);max-width:42ch}

/* 空状态：行动邀请而非冰冷报错 */
.empty{
  margin:0 clamp(20px,4vw,56px) var(--sp-16);
  border:1px solid var(--line-hard);background:var(--paper);
  padding:var(--sp-10) var(--sp-8);font-size:16px;line-height:1.7;color:var(--ink-2);
  display:grid;gap:var(--sp-2);justify-items:start;
}
.empty-mark{font-size:20px;color:var(--magenta);line-height:1}
.empty strong{font-size:20px;color:var(--ink);letter-spacing:-.01em}
.empty a{color:var(--cobalt);font-weight:600;text-underline-offset:3px}
#empty[hidden],.svc-body[hidden]{display:none}

/* ============ 服务表 ============ */
.svc-list{border-top:1px solid var(--line)}
.svc{border-bottom:1px solid var(--line);transition:background .24s var(--ease)}
.svc-btn{
  width:100%;display:grid;grid-template-columns:64px 1fr auto 32px;
  align-items:center;gap:var(--sp-5);text-align:left;
  background:none;border:0;cursor:pointer;
  padding:var(--sp-6) clamp(20px,4vw,56px);min-height:44px;
  transition:background .2s var(--ease);
}
.svc-btn:hover{background:var(--cobalt-tint)}
.svc-no{font-family:var(--f-mono);font-size:13px;font-weight:700;color:var(--magenta)}
.svc-name{font-size:clamp(20px,2.2vw,28px);font-weight:600;letter-spacing:-.025em}
.svc-range{font-family:var(--f-mono);font-size:14px;color:var(--muted);white-space:nowrap}
.svc-sign{position:relative;width:16px;height:16px;justify-self:end}
.svc-sign::before,.svc-sign::after{
  content:"";position:absolute;background:var(--ink);transition:transform .26s var(--ease)}
.svc-sign::before{left:0;top:7px;width:16px;height:2px}
.svc-sign::after{left:7px;top:0;width:2px;height:16px}
.svc-btn[aria-expanded="true"] .svc-sign::after{transform:scaleY(0)}
.svc-btn[aria-expanded="true"]{background:var(--cobalt-tint)}

.svc-body{overflow:hidden}
.svc-cols{display:grid;grid-template-columns:1fr 1fr;gap:var(--sp-8);
  padding:0 clamp(20px,4vw,56px) var(--sp-10)}
.svc-cols h4{font-size:12px;font-family:var(--f-mono);font-weight:700;letter-spacing:.1em;
  color:var(--cobalt);margin-bottom:var(--sp-3)}
.svc-cols li{font-size:15px;line-height:1.65;color:var(--ink-2);
  padding-left:var(--sp-5);position:relative;margin-bottom:var(--sp-2)}
.svc-cols li::before{content:"";position:absolute;left:0;top:.72em;
  width:10px;height:1px;background:var(--line-hard)}

/* M4 跨区联动：悬停项目时对应服务行亮起 */
.svc.is-linked{background:var(--magenta-tint)}
.svc.is-linked .svc-no{color:var(--cobalt)}

/* ============ 工作室 ============ */
.studio{display:grid;grid-template-columns:2fr 8fr;gap:var(--sp-8);
  padding:clamp(48px,7vw,96px) clamp(20px,4vw,56px);
  border-top:1px solid var(--line-hard);border-bottom:1px solid var(--line-hard)}
.studio-no{font-family:var(--f-mono);font-size:13px;font-weight:700;letter-spacing:.08em;
  color:var(--muted);padding-top:var(--sp-2)}
.studio-body h2{font-size:clamp(28px,3.4vw,46px);line-height:1.18;font-weight:600;
  letter-spacing:-.03em;margin-bottom:var(--sp-6);max-width:22ch}
.studio-body p{font-size:16px;line-height:1.75;color:var(--ink-2);max-width:62ch;margin-bottom:var(--sp-4)}
.studio-body p:last-child{color:var(--muted);font-size:15px}

/* ============ 联系 ============ */
.contact{display:grid;grid-template-columns:5fr 7fr;gap:clamp(32px,5vw,80px);
  padding:clamp(48px,7vw,96px) clamp(20px,4vw,56px)}
.ct-intro h2{font-size:clamp(32px,4.4vw,56px);line-height:1.04;font-weight:600;
  letter-spacing:-.045em;margin-bottom:var(--sp-6)}
.ct-intro p{font-size:16px;line-height:1.75;color:var(--ink-2);max-width:40ch}
.ct-mail{margin-top:var(--sp-6);font-family:var(--f-mono);font-size:15px;font-weight:600;
  color:var(--cobalt);border-top:1px solid var(--line-hard);padding-top:var(--sp-4);
  overflow-wrap:anywhere}

.ct-form{display:grid;grid-template-columns:1fr 1fr;gap:var(--sp-6)}
.field{display:flex;flex-direction:column;gap:var(--sp-2)}
.field--full,.ct-actions,.form-status{grid-column:1/-1}
.field label{font-size:14px;font-weight:600}
.field input,.field select,.field textarea{
  font-family:inherit;font-size:16px;color:var(--ink);
  background:var(--paper);border:1px solid var(--line-hard);border-radius:0;
  padding:var(--sp-3) var(--sp-4);min-height:44px;
  transition:border-color .18s var(--ease),box-shadow .18s var(--ease)}
.field textarea{resize:vertical;line-height:1.6;min-height:112px}
.field input:hover,.field select:hover,.field textarea:hover{border-color:var(--ink-2)}
.field input:focus,.field select:focus,.field textarea:focus{
  outline:none;border-color:var(--cobalt);box-shadow:0 0 0 3px var(--cobalt-tint)}
.hint{font-size:13px;line-height:1.5;color:var(--muted);display:none}
.field[data-state="error"] .hint{display:block;color:var(--magenta);font-weight:600}
.field[data-state="error"] input,
.field[data-state="error"] select,
.field[data-state="error"] textarea{border-color:var(--magenta);box-shadow:0 0 0 3px var(--magenta-tint)}

.ct-actions{display:flex;align-items:center;gap:var(--sp-5);flex-wrap:wrap;margin-top:var(--sp-2)}
.btn-primary{
  font-size:15px;font-weight:700;
  background:var(--cobalt);color:var(--bone);border:1px solid var(--cobalt);
  padding:var(--sp-4) var(--sp-8);min-height:48px;cursor:pointer;
  transition:background .18s var(--ease),transform .18s var(--ease)}
.btn-primary:hover{background:var(--cobalt-dp)}
.btn-primary:active{transform:scale(.98)}
.ct-note{font-size:13px;color:var(--muted);max-width:30ch}
.form-status{font-size:15px;font-weight:600;color:var(--cobalt);min-height:1.6em;line-height:1.6}
.form-status[data-tone="error"]{color:var(--magenta)}

/* ============ 页脚 ============ */
.site-foot{background:var(--ink);color:var(--bone);
  padding:clamp(40px,5vw,72px) clamp(20px,4vw,56px) var(--sp-8)}
.foot-mark{font-size:clamp(40px,7vw,96px);font-weight:600;letter-spacing:-.05em;line-height:.9}
.foot-cols{display:flex;flex-wrap:wrap;gap:var(--sp-8);justify-content:space-between;
  margin-top:var(--sp-8);border-top:1px solid rgba(247,245,240,.24);padding-top:var(--sp-5)}
.foot-cols p{font-size:15px;color:rgba(247,245,240,.88);overflow-wrap:anywhere}
.foot-fine{margin-top:var(--sp-10);font-size:13px;line-height:1.6;
  color:rgba(247,245,240,.72);max-width:72ch}

/* ============ 减少动效 ============ */
@media (prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *{transition:none!important;animation:none!important}
  .card:hover{transform:none}
}

/* ============ 1080 以下：单列纵向流 ============ */
@media (max-width:1080px){
  .hero-grid{grid-template-columns:1fr;gap:var(--sp-8);align-items:start}
  .hero-lead{max-width:48ch}
  .hero-facts{grid-template-columns:repeat(3,1fr);gap:var(--sp-5)}
  .hero-facts>div{grid-template-columns:1fr;gap:var(--sp-1)}
  .grid{grid-template-columns:1fr;gap:var(--sp-10)}
  .card--wide{grid-row:auto}
  .plate{aspect-ratio:4/3;flex:0 0 auto;min-height:0}
  .studio{grid-template-columns:1fr;gap:var(--sp-5)}
  .contact{grid-template-columns:1fr}
  .svc-cols{grid-template-columns:1fr;gap:var(--sp-6)}
}

@media (max-width:760px){
  .site-head{grid-template-columns:auto auto;gap:var(--sp-4);padding:var(--sp-4) var(--sp-5)}
  .site-nav{grid-column:1/-1;justify-self:start;gap:var(--sp-5);
    order:3;border-top:1px solid var(--line);padding-top:var(--sp-2);width:100%}
  .site-nav a{padding:var(--sp-3) 0;font-size:14px}
  .head-cta{justify-self:end;padding:var(--sp-3) var(--sp-4);font-size:13px}
  .wordmark{font-size:24px}

  .hero{padding:var(--sp-8) var(--sp-5) var(--sp-10)}
  .eyebrow{font-size:12px;letter-spacing:.04em;margin-bottom:var(--sp-6);
    display:flex;flex-direction:column;gap:var(--sp-1);line-height:1.5}
  .hero-lead{font-size:17px}
  .hero-facts{grid-template-columns:1fr;gap:0}
  .hero-facts>div{grid-template-columns:10ch 1fr;padding:var(--sp-3) 0}

  .section-bar{flex-direction:column;align-items:stretch;gap:var(--sp-3);
    padding:var(--sp-4) var(--sp-5)}
  .tabs{width:100%}
  .tabs button{flex:1 1 auto;padding:var(--sp-2) var(--sp-3)}

  .grid{padding:var(--sp-8) var(--sp-5) var(--sp-12);gap:var(--sp-8)}
  .cap{flex-direction:column;gap:var(--sp-1)}
  .cap-meta{text-align:left}
  .empty{margin:0 var(--sp-5) var(--sp-12);padding:var(--sp-8) var(--sp-5)}
  .sheet{transform:rotate(-2deg)}
  .plate--mist .art-word{font-size:clamp(28px,7vw,44px)}

  .svc-btn{grid-template-columns:40px 1fr 24px;gap:var(--sp-3);
    padding:var(--sp-5) var(--sp-5);row-gap:var(--sp-1)}
  .svc-range{grid-column:2/3;font-size:13px}
  .svc-sign{grid-column:3/4;grid-row:1/3}
  .svc-body .svc-cols{padding:0 var(--sp-5) var(--sp-8)}

  .studio{padding:var(--sp-12) var(--sp-5)}
  .contact{padding:var(--sp-12) var(--sp-5) var(--sp-16)}
  .ct-form{grid-template-columns:1fr;gap:var(--sp-5)}
  .ct-actions{flex-direction:column;align-items:stretch;gap:var(--sp-4)}
  .btn-primary{width:100%;padding:var(--sp-4)}
  .ct-note{max-width:none}
  .site-foot{padding:var(--sp-12) var(--sp-5) var(--sp-6)}
}

@media (max-width:420px){
  .hero h1{font-size:clamp(46px,16vw,68px)}
  .tabs button{font-size:13px}
  .cap h3{font-size:16px}
  .cap-line{font-size:14px}
}

