/* FORM · 交互层
   1) 项目筛选：标准 tablist 键盘模式（← → Home End）
   2) 服务原位展开（D4）
   3) 项目 ↔ 服务跨区语义联动（M4）
   4) 联系表单校验 / 错误 / 提交态
*/
(function () {
  'use strict';

  /* ---------- 1. 筛选 ---------- */
  var tabs   = Array.prototype.slice.call(document.querySelectorAll('[role="tab"]'));
  var cards  = Array.prototype.slice.call(document.querySelectorAll('#grid .card'));
  var empty  = document.getElementById('empty');
  var status = document.getElementById('status');

  function filter(cat, label) {
    var shown = 0;
    cards.forEach(function (card) {
      var show = cat === 'all' || card.dataset.cat === cat;
      card.hidden = !show;
      if (show) shown++;
    });
    if (status) {
      status.textContent = cat === 'all'
        ? '显示全部 ' + shown + ' 个项目'
        : '显示「' + label + '」类别的 ' + shown + ' 个项目';
    }
    if (empty) empty.hidden = shown !== 0;
  }

  function selectTab(tab) {
    tabs.forEach(function (t) {
      var on = t === tab;
      t.setAttribute('aria-selected', on ? 'true' : 'false');
      t.tabIndex = on ? 0 : -1;
    });
    filter(tab.dataset.cat, tab.textContent.trim());
  }

  tabs.forEach(function (tab, i) {
    tab.addEventListener('click', function () { selectTab(tab); });
    tab.addEventListener('keydown', function (e) {
      var k = e.key, next = -1;
      if (k === 'ArrowRight' || k === 'ArrowDown') next = (i + 1) % tabs.length;
      else if (k === 'ArrowLeft' || k === 'ArrowUp') next = (i - 1 + tabs.length) % tabs.length;
      else if (k === 'Home') next = 0;
      else if (k === 'End') next = tabs.length - 1;
      if (next > -1) { e.preventDefault(); tabs[next].focus(); selectTab(tabs[next]); }
    });
  });

  /* ---------- 2 & 3. 服务展开 + 跨区联动 ---------- */
  var svcBtns  = Array.prototype.slice.call(document.querySelectorAll('.svc-btn'));
  var svcItems = Array.prototype.slice.call(document.querySelectorAll('.svc'));

  svcBtns.forEach(function (btn) {
    var body = document.getElementById(btn.getAttribute('aria-controls'));
    btn.addEventListener('click', function () {
      var open = btn.getAttribute('aria-expanded') === 'true';
      btn.setAttribute('aria-expanded', open ? 'false' : 'true');
      if (body) body.hidden = open;
    });
  });

  // M4：悬停 / 聚焦项目 → 对应服务行亮起，建立隐形呼应
  cards.forEach(function (card) {
    var kind = card.dataset.cat;
    function link(on) {
      svcItems.forEach(function (item) {
        if (item.dataset.svc === kind) item.classList.toggle('is-linked', on);
      });
    }
    card.addEventListener('mouseenter', function () { link(true); });
    card.addEventListener('mouseleave', function () { link(false); });
    card.addEventListener('focusin',    function () { link(true); });
    card.addEventListener('focusout',   function () { link(false); });
  });

  /* ---------- 4. 表单 ---------- */
  var form = document.getElementById('enquiry');
  if (!form) return;

  var fStatus = document.getElementById('form-status');
  var fields = [
    { el: document.getElementById('f-name'), test: function (v) { return v.trim().length >= 2; } },
    { el: document.getElementById('f-mail'), test: function (v) { return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v.trim()); } },
    { el: document.getElementById('f-type'), test: function (v) { return v !== ''; } },
    { el: document.getElementById('f-msg'),  test: function (v) { return v.trim().length >= 8; } }
  ];

  function wrapOf(el) { return el.closest('.field'); }

  function check(f, quiet) {
    var ok = f.test(f.el.value);
    var wrap = wrapOf(f.el);
    if (ok) { wrap.dataset.state = 'ok'; f.el.removeAttribute('aria-invalid'); }
    else if (!quiet) { wrap.dataset.state = 'error'; f.el.setAttribute('aria-invalid', 'true'); }
    return ok;
  }

  fields.forEach(function (f) {
    if (!f.el) return;
    f.el.addEventListener('blur',  function () { check(f); });
    f.el.addEventListener('input', function () {
      if (wrapOf(f.el).dataset.state === 'error') check(f);
    });
  });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    var firstBad = null;
    fields.forEach(function (f) { if (f.el && !check(f) && !firstBad) firstBad = f.el; });

    if (firstBad) {
      fStatus.dataset.tone = 'error';
      fStatus.textContent = '还有一处需要补充，已为你定位到那一条。';
      firstBad.focus();
      return;
    }
    fStatus.dataset.tone = 'ok';
    fStatus.textContent = '已收到（概念样板，不会真的发出）：' +
      form.name.value.trim() + '，我们会在两个工作日内回复 ' + form.mail.value.trim() + '。';
    form.reset();
    fields.forEach(function (f) { if (f.el) delete wrapOf(f.el).dataset.state; });
  });
})();
